function APR:ActivateRouteFromTemporaryTrigger(routeKey)
    if not routeKey then
        return
    end
    if self.CanStartRoute and not self:CanStartRoute(routeKey) then return end

    local routeName = getRouteDisplayName(routeKey, self.RouteTriggersSuggestion.routes[routeKey])
    APRCustomPath[self.PlayerID] = APRCustomPath[self.PlayerID] or {}
    APRCustomPath[self.PlayerID][1] = routeName

    APR:ActivateRoute(routeKey)
    if APR.XPBuffOverlay then APR.XPBuffOverlay:QueueRefresh() end
    self:SetRouteProgress(routeKey, APRData[self.PlayerID][routeKey] or 1, "route_suggestion")
    APRData[self.PlayerID][routeKey .. "-SkippedStep"] = APRData[self.PlayerID][routeKey .. "-SkippedStep"] or 0

    self:UpdateMapId()
    self:UpdateStep()
end--[[APR_DIAG]]; APR.ActivateRouteFromTemporaryTrigger = APRTrace("APR-Core/features/questing/RouteSuggestions.lua:256:APR:ActivateRouteFromTemporaryTrigger#13", APR.ActivateRouteFromTemporaryTrigger)--[[/APR_DIAG]]

